<script setup lang="ts">import {computed,shallowRef} from 'vue';import EquipoEngraseListItem from './EquipoEngraseListItem.vue';import type {EquipoEngraseListItem as EquipoItem} from '@/stores/dbequipos/engrase/filtrosEngrase.types';const props=defineProps<{equipos:EquipoItem[];selectedEquipoId:number|null;countsByTipo:[string,number][];loading:boolean;error:string|null}>();defineEmits<{selectEquipo:[number];retry:[]}>();const search=shallowRef('');const visible=computed(()=>{const q=search.value.toLowerCase();return props.equipos.filter(x=>!q||[x.codigo,x.tipo_equipo,x.subtipo??''].some(v=>v.toLowerCase().includes(q)))});</script>
<template><section class="flex min-h-0 flex-col gap-3 rounded-lg border border-gray-200 bg-white p-3 shadow-sm"><header><h2 class="text-sm font-bold text-main">Equipos <span class="font-normal text-gray-500">({{equipos.length}})</span></h2></header><input v-model="search" class="h-8 rounded-md border border-gray-200 px-2 text-sm" placeholder="Buscar equipo…"><div class="flex flex-wrap gap-1"><span v-for="([name,count]) in countsByTipo" :key="name" class="rounded bg-second px-1.5 py-1 text-xs text-gray-600">{{name}} <b class="text-main">{{count}}</b></span></div><p v-if="loading" class="p-3 text-center text-xs text-gray-500">Cargando equipos…</p><p v-else-if="error" class="p-3 text-center text-xs text-danger">{{error}} <button class="font-semibold underline" @click="$emit('retry')">Reintentar</button></p><p v-else-if="!visible.length" class="p-3 text-center text-xs text-gray-500">No hay equipos con estos filtros.</p><div v-else class="grid gap-2 overflow-auto"><EquipoEngraseListItem v-for="equipo in visible" :key="equipo.id" :equipo="equipo" :selected="equipo.id===selectedEquipoId" @select="$emit('selectEquipo',$event)"/></div></section></template>
